package com.franco.desco.adapter.in.web.cultivation;
import com.franco.desco.application.cultivation.CultivationCommands;import com.franco.desco.application.shared.pagination.PageRequest;import com.franco.desco.domain.cultivation.CultivationModels;import org.springframework.stereotype.Component;
@Component public class CultivationWebMapper{
 public CultivationCommands.ListCultivations list(int p,int s,Long predioId,Long socioId,Long variedadId,String situacion,String buscar){return new CultivationCommands.ListCultivations(new PageRequest<>(p,s,new CultivationCommands.Filter(predioId,socioId,variedadId,situacion,buscar),null,null));}
 public CultivationResponses.Summary response(CultivationModels.Summary v){return new CultivationResponses.Summary(v.parcelaId(),v.predioId(),v.predioCodigo(),v.predioNombre(),v.parcelaCodigo(),v.parcelaNombre(),v.areaHa(),v.ubicacionId(),v.parcelaEstado(),v.parcelaCultivoId(),v.variedadPaltaId(),v.variedad(),v.fechaInicio(),v.fechaFin(),v.situacionCultivo(),v.cultivoEstado());}
 public CultivationResponses.Detail response(CultivationModels.Detail v){var p=v.parcela();return new CultivationResponses.Detail(new CultivationResponses.Plot(p.parcelaId(),p.predioId(),p.predioCodigo(),p.predioNombre(),p.codigo(),p.nombre(),p.areaHa(),p.estado(),p.ubicacionId(),p.distritoCodigo(),p.centroPobladoId(),p.referencia(),p.latitud(),p.longitud(),p.altitudM()),v.cultivos().stream().map(x->new CultivationResponses.Crop(x.parcelaCultivoId(),x.variedadPaltaId(),x.variedadCodigo(),x.variedad(),x.fechaInicio(),x.fechaFin(),x.situacionCultivo(),x.estado())).toList(),v.censos().stream().map(x->new CultivationResponses.Census(x.censoPlantasId(),x.parcelaCultivoId(),x.fechaCenso(),x.plantasTotales(),x.plantasProductivas(),x.plantasNoProductivas(),x.plantasNuevas(),x.plantasMuertas(),x.plantasAfectadas(),x.observacion(),x.estado())).toList(),v.evaluaciones().stream().map(x->new CultivationResponses.Evaluation(x.evaluacionAgronomicaId(),x.visitaTecnicaId(),x.parcelaCultivoId(),x.tipoEvaluacionId(),x.tipoEvaluacion(),x.fechaHora(),x.resultado(),x.observacion(),x.estado())).toList(),v.archivos().stream().map(x->new CultivationResponses.FileRef(x.archivoId(),x.nombreOriginal(),x.mimeType(),x.secureUrl(),x.fechaCarga(),x.categoria(),x.origenCaptura(),x.parcelaId(),x.parcelaCultivoId(),x.censoPlantasId(),x.evaluacionAgronomicaId())).toList());}
}
